// intent: Test parsing with a custom small buffer set via setvbuf on the FILE stream.
#include <nlohmann/json.hpp>
#include <cstdio>
#include <iostream>
int main() {
    std::FILE* f = std::tmpfile();
    if (!f) return 0;
    char small_buf[10];
    std::setvbuf(f, small_buf, _IOFBF, sizeof(small_buf));
    const char* content = "{\"a\": 1, \"b\": 2, \"c\": 3, \"long_string_to_force_buffer_refill\": true}";
    std::fputs(content, f);
    std::rewind(f);
    try {
        auto j = nlohmann::json::parse(f);
        std::cout << j.size() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    std::fclose(f);
}
